INSERT INTO `faq` (`faq_id`,`category`,`question`,`answer`) VALUES
('FAQ001','위험지수','위험지수는 무엇을 의미하나요?','제공된 점수 CSV의 total_risk_score를 주차장 관리번호로 연결한 0~100점 상대 위험도입니다. 점수 파일에 값이 없는 주차장은 미산정으로 표시합니다.'),
('FAQ002','위험지수','위험도가 낮으면 안전한가요?','상대적으로 낮은 점수는 안전을 보장하지 않습니다. 현장 통제와 기상특보를 함께 확인하세요.'),
('FAQ003','서비스 이용','실시간 침수 상황을 알 수 있나요?','실시간 상황을 관측하거나 미래 침수를 예측하지 않습니다. 2025년 데이터 분석을 전제로 한 프로토타입입니다.'),
('FAQ004','서비스 이용','위치를 허용하지 않아도 이용할 수 있나요?','네. 처음에는 색동공원(강북구)을 임시 기준점으로 사용합니다. 지도 위 ‘◎ 현재 위치’에서 ‘GPS로 내 위치 찾기’를 누르고 브라우저 위치 권한을 허용하면 기기 위치를, 허용하지 않으면 기준 위치를 고르거나 좌표를 입력해 검색 반경, 주변 주차장 목록과 거리를 그 위치 기준으로 갱신합니다.'),
('FAQ005','데이터','어떤 데이터를 사용하나요?','최종 위험지수는 제공된 점수 CSV에서 읽습니다. 상세 화면의 참고 지표는 저지대 점수·자치구별 강수량·침수심 자료에서 가져옵니다. 집중호우는 같은 날짜의 연속 3시간 강수량이 60mm를 초과한 날을 하루 한 번 집계합니다.');
